+
+func TestSeedIgnoredReportsAListingFailureForANonGitSource(t *testing.T) {
+	src := t.TempDir()
+	// Keep git from finding a repository above the temporary source.
+	t.Setenv("GIT_CEILING_DIRECTORIES", filepath.Dir(src))
+	seedWrite(t, src, "build/cache", "cache\n")
+	seedWrite(t, src, "tracked.txt", "t\n")
+	dst := t.TempDir()
+
+	err := SeedIgnored(src, dst)
+	if err == nil {
+		t.Fatal("SeedIgnored of a source that is not a Git repository returned no error")
+	}
+	for _, want := range []string{src, "listing ignored paths"} {
+		if !strings.Contains(err.Error(), want) {
+			t.Errorf("error %q does not contain %q", err, want)
+		}
+	}
+	entries, readErr := os.ReadDir(dst)
+	if readErr != nil {
+		t.Fatal(readErr)
+	}
+	for _, e := range entries {
+		t.Errorf("failed SeedIgnored left %s in the destination", e.Name())
+	}
+}

